          "hint": "Use KE = ½mv²",
          "subject": "physics",
          "chapter": "energy",
          "topic": "Kinetic & Potential Energy",
          "conceptId": "physics_energy_kinetic_potential_energy",
          "skillId": "physics_energy",
          "subskillId": "physics_energy_q1"
